CREATE TABLE public.player_firearms (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, gun_id text NOT NULL DEFAULT 'gun_crystal', rounds integer NOT NULL DEFAULT 12 CHECK(rounds BETWEEN 0 AND 12), last_shot_at timestamptz NOT NULL DEFAULT '-infinity', reload_until timestamptz NOT NULL DEFAULT '-infinity');
GRANT SELECT ON public.player_firearms TO authenticated; GRANT ALL ON public.player_firearms TO service_role;
ALTER TABLE public.player_firearms ENABLE ROW LEVEL SECURITY;
CREATE POLICY firearms_read ON public.player_firearms FOR SELECT TO authenticated USING(true);
CREATE TABLE public.player_wallets (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, gralats bigint NOT NULL DEFAULT 0 CHECK(gralats>=0));
GRANT SELECT ON public.player_wallets TO authenticated; GRANT ALL ON public.player_wallets TO service_role;
ALTER TABLE public.player_wallets ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallets_read ON public.player_wallets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.ensure_firearms() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); BEGIN INSERT INTO public.player_firearms(user_id) VALUES(uid) ON CONFLICT DO NOTHING; INSERT INTO public.player_wallets(user_id) VALUES(uid) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.equip_firearm(_gun text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); BEGIN PERFORM public.ensure_firearms(); IF _gun NOT IN ('gun_crystal','gun_pulse','gun_carbine') AND NOT EXISTS(SELECT 1 FROM public.player_art WHERE 'custom:'||id::text=_gun AND user_id=uid AND kind='melee') THEN RAISE EXCEPTION 'Invalid weapon'; END IF; UPDATE public.player_firearms SET gun_id=_gun WHERE user_id=uid; END $$;
CREATE OR REPLACE FUNCTION public.reload_firearm() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); BEGIN PERFORM public.ensure_firearms(); UPDATE public.player_firearms SET rounds=12,reload_until=now()+interval '1.2 seconds' WHERE user_id=uid AND reload_until<=now(); END $$;
CREATE OR REPLACE FUNCTION public.award_gralats(_user uuid,_amount integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.am_admin() THEN RAISE EXCEPTION 'Admin only'; END IF; IF _amount IS NULL OR _amount<1 OR _amount>1000000 THEN RAISE EXCEPTION 'Invalid amount'; END IF; INSERT INTO public.player_wallets(user_id,gralats) VALUES(_user,_amount) ON CONFLICT(user_id) DO UPDATE SET gralats=public.player_wallets.gralats+excluded.gralats; END $$;
CREATE OR REPLACE FUNCTION public.resolve_firearm_shot(_attacker uuid,_target uuid,_aim text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE a public.player_positions; b public.player_positions; f public.player_firearms; ct public.player_combat; ga uuid; gb uuid; dx real; dy real; forward real; sideways real; rp record; seq integer;
BEGIN
IF _aim NOT IN ('up','down','left','right') OR _aim IS NULL THEN RAISE EXCEPTION 'Invalid aim'; END IF;
SELECT * INTO a FROM public.player_positions WHERE user_id=_attacker;
IF a.user_id IS NULL OR a.updated_at<now()-interval '4 seconds' THEN RAISE EXCEPTION 'Connection out of sync'; END IF;
SELECT * INTO f FROM public.player_firearms WHERE user_id=_attacker FOR UPDATE;
IF f.user_id IS NULL THEN RAISE EXCEPTION 'Weapon not ready'; END IF;
IF f.rounds=0 THEN RAISE EXCEPTION 'Recarga el arma'; END IF;
IF f.reload_until>now() OR f.last_shot_at>now()-interval '0.3 seconds' THEN RAISE EXCEPTION 'Espera un momento'; END IF;
UPDATE public.player_firearms SET rounds=rounds-1,last_shot_at=now() WHERE user_id=_attacker;
IF _target IS NULL THEN RETURN jsonb_build_object('rounds',f.rounds-1,'damage',0,'hp',0,'max_hp',0,'killed',false,'targetId',NULL); END IF;
SELECT * INTO b FROM public.player_positions WHERE user_id=_target;
dx:=b.x-a.x; dy:=b.y-a.y;
forward:=CASE _aim WHEN 'up' THEN -dy WHEN 'down' THEN dy WHEN 'left' THEN -dx ELSE dx END;
sideways:=CASE WHEN _aim IN ('up','down') THEN abs(dx) ELSE abs(dy) END;
SELECT * INTO ct FROM public.player_combat WHERE user_id=_target FOR UPDATE;
ga:=public.gang_of(_attacker); gb:=public.gang_of(_target);
IF _target=_attacker OR b.user_id IS NULL OR b.map_id<>a.map_id OR b.updated_at<now()-interval '4 seconds' OR forward<=0 OR forward>240 OR sideways>12 OR ct.user_id IS NULL OR ct.protected_until>now() OR (public.cfg('friendly_fire')=0 AND ga IS NOT NULL AND gb IS NOT NULL AND (ga=gb OR public.are_allied(ga,gb))) THEN RETURN jsonb_build_object('rounds',f.rounds-1,'damage',0,'hp',0,'max_hp',0,'killed',false,'targetId',NULL); END IF;
IF ct.hp>1 THEN UPDATE public.player_combat SET hp=hp-1,updated_at=now() WHERE user_id=_target;
ELSE SELECT * INTO rp FROM public.respawn_point(_target); seq:=ct.respawn_seq+1;
INSERT INTO public.player_respawns(user_id,killer_id,base_id,map_id,x,y,seq) VALUES(_target,_attacker,rp.base_id,rp.map_id,rp.x,rp.y,seq);
UPDATE public.player_combat SET hp=LEAST(ct.max_hp,public.cfg('respawn_hp')::int),deaths=deaths+1,respawn_seq=seq,respawn_map=rp.map_id,respawn_x=rp.x,respawn_y=rp.y,protected_until=now()+make_interval(secs=>public.cfg('protection_seconds')::double precision),updated_at=now() WHERE user_id=_target;
UPDATE public.player_combat SET kills=kills+1 WHERE user_id=_attacker;
UPDATE public.player_positions SET map_id=rp.map_id,x=rp.x,y=rp.y,updated_at=now() WHERE user_id=_target;
UPDATE public.profiles SET map_id=rp.map_id,pos_x=rp.x,pos_y=rp.y WHERE id=_target; END IF;
RETURN jsonb_build_object('rounds',f.rounds-1,'damage',1,'hp',greatest(0,ct.hp-1),'max_hp',ct.max_hp,'killed',ct.hp<=1,'targetId',_target);
END $$;
REVOKE ALL ON FUNCTION public.ensure_firearms(),public.equip_firearm(text),public.reload_firearm(),public.award_gralats(uuid,integer),public.resolve_firearm_shot(uuid,uuid,text) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.resolve_firearm_shot(uuid,uuid,text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.ensure_firearms(),public.equip_firearm(text),public.reload_firearm(),public.award_gralats(uuid,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_firearm_shot(uuid,uuid,text) TO service_role;